import { PraxisQuestion } from "./types";

export const PRAXIS_QUESTIONS: PraxisQuestion[] = [
  { id:"b-reading-1", subtest:"reading", question:`A kindergarten teacher claps syllables while reading aloud "el-e-phant." Which skill is the teacher directly assessing?`, options:[`Phonological awareness`,`Phonemic awareness`,`Alphabetic principle`,`Phonics decoding`], answer:0, explanation:`Syllable awareness is a component of phonological awareness, which involves manipulating larger sound units before individual phonemes.`, verified:true },
  { id:"b-reading-2", subtest:"reading", question:`Which pair of words demonstrates a rhyming pattern that a first-grader should recognize?`, options:[`cat, cut`,`moon, spoon`,`dog, door`,`sun, song`], answer:1, explanation:`Moon and spoon have the same final sound (-oon), making them a clear rhyming pair. This is a foundational phonological awareness skill.`, verified:true },
  { id:"b-reading-3", subtest:"reading", question:`A teacher shows a child the word 'bike' and asks, 'What sound does the 'e' make at the end?' The child is being assessed on understanding of which concept?`, options:[`Phoneme segmentation`,`Vowel digraphs`,`Silent e rule`,`Concepts of print`], answer:2, explanation:`The silent 'e' rule (CVCe pattern) is a key alphabetic principle showing how a final 'e' changes the vowel sound.`, verified:true },
  { id:"b-reading-4", subtest:"reading", question:`When a child can blend sounds /c/ /a/ /t/ into 'cat,' which phonemic awareness skill has been demonstrated?`, options:[`Phoneme isolation`,`Phoneme substitution`,`Phoneme segmentation`,`Phoneme blending`], answer:3, explanation:`Phoneme blending is the ability to combine individual phonemes into a word. This is essential for decoding.`, verified:true },
  { id:"b-reading-5", subtest:"reading", question:`A student reads 'wish' when presented with the word 'with.' Which cueing system did the student primarily rely on?`, options:[`Graphophonic cues`,`Syntactic cues`,`Semantic cues`,`Visual structure`], answer:0, explanation:`The student used graphophonic (sound-letter) cues to decode but made an error, showing they attended to initial and final letters but misread the medial vowel.`, verified:true },
  { id:"b-reading-6", subtest:"reading", question:`Which word contains a consonant blend at the beginning?`, options:[`ship`,`bring`,`that`,`phone`], answer:1, explanation:`'Bring' starts with /br/, a consonant blend where both sounds are pronounced. 'Ship,' 'that,' and 'phone' begin with single consonant sounds or digraphs.`, verified:true },
  { id:"b-reading-7", subtest:"reading", question:`A first-grade teacher is teaching the digraph 'ch.' Which word best exemplifies this sound?`, options:[`church`,`each`,`choose`,`school`], answer:2, explanation:`In 'choose,' 'ch' represents the /ch/ sound. In 'school,' 'ch' is not present; in 'each,' 'ch' is at the end; 'church' works but 'choose' is the most straightforward example.`, verified:true },
  { id:"b-reading-8", subtest:"reading", question:`Which syllable-type category includes words like 'make,' 'save,' and 'note'?`, options:[`Closed syllable`,`Open syllable`,`Vowel team syllable`,`Vowel-consonant-e syllable`], answer:3, explanation:`The vowel-consonant-e (CVCe) pattern has a silent final 'e' that makes the middle vowel long.`, verified:true },
  { id:"b-reading-9", subtest:"reading", question:`A student reads 'read' (present tense) as 'red' (past tense, rhyming with 'bed'). This error most likely indicates a misunderstanding of which concept?`, options:[`Word meaning and context`,`Sight word automaticity`,`Vowel team patterns`,`Phoneme isolation`], answer:0, explanation:`The student decoded the letters correctly but used context inappropriately, not recognizing that 'read' can have two pronunciations and needs contextual/semantic understanding.`, verified:true },
  { id:"b-reading-10", subtest:"reading", question:`Which word is best classified as a sight word for early first grade?`, options:[`jump`,`the`,`running`,`wonderful`], answer:1, explanation:`'The' is a high-frequency sight word essential for early reading. 'Jump' and 'running' follow decodable patterns; 'wonderful' is too advanced.`, verified:true },
  { id:"b-reading-11", subtest:"reading", question:`A teacher asks a student to say the first sound in 'stop.' The student responds '/s/.' Which phonemic awareness skill has been demonstrated?`, options:[`Phoneme blending`,`Phoneme segmentation`,`Phoneme isolation`,`Phoneme substitution`], answer:2, explanation:`Phoneme isolation is the ability to identify an individual sound within a word.`, verified:true },
  { id:"b-reading-12", subtest:"reading", question:`Which instructional approach is MOST effective for teaching r-controlled vowel patterns like 'car,' 'her,' and 'for'?`, options:[`Whole-word memorization only`,`Incidental exposure through reading`,`Teaching each word's pronunciation separately without pattern recognition`,`Explicit instruction of the r-controlled vowel pattern with multiple examples`], answer:3, explanation:`Explicit instruction of patterns with multiple examples helps students recognize and apply the r-controlled vowel rule across many words.`, verified:true },
  { id:"b-reading-13", subtest:"reading", question:`A student writes 'kat' instead of 'cat.' This spelling error suggests the student understands which concept but may need refinement?`, options:[`Phonemic awareness and phonics`,`Letter names`,`Capitalization rules`,`Sight word recognition`], answer:0, explanation:`The student correctly mapped sounds to letters (phonemic awareness and phonics) but chose /k/ instead of /c/ for the /c/ sound, showing phonemic awareness is present but needs refinement on sound-symbol choices.`, verified:true },
  { id:"b-reading-14", subtest:"reading", question:`Which sequence BEST represents a developmentally appropriate scope and sequence for phonics instruction?`, options:[`Consonant digraphs, then short vowels, then long vowels, then blends`,`Short vowels, then consonant blends and digraphs, then long vowels, then r-controlled vowels`,`Letter names, then sight words, then blends, then all vowel patterns`,`Vowel teams, then digraphs, then short vowels, then blends`], answer:1, explanation:`Typical scope and sequence begins with short vowels (foundational), then teaches blends and digraphs for decoding multisyllabic words, then long vowels, then r-controlled vowels.`, verified:true },
  { id:"b-reading-15", subtest:"reading", question:`A student reads 'The cat sat on the mat' with 98% accuracy and fluent prosody. According to reading level benchmarks, this performance indicates which level of text?`, options:[`Frustration level`,`Instructional level`,`Independent level`,`Guided reading level`], answer:2, explanation:`98% accuracy (word recognition 95-100%) indicates independent reading level, where the reader can read without teacher support.`, verified:true },
  { id:"b-reading-16", subtest:"reading", question:`A running record shows a student read 'horse' when the text said 'house.' The student then self-corrected. This behavior demonstrates which reading strategy?`, options:[`Graphophonic cueing only`,`Sight word memorization`,`Random guessing`,`Self-monitoring and using multiple cueing systems`], answer:3, explanation:`Self-correction shows the reader is monitoring for meaning and cross-checking sound-letter cues with semantic sense, a sign of strategic reading.`, verified:true },
  { id:"b-reading-17", subtest:"reading", question:`Which approach is MOST research-based for vocabulary instruction in elementary grades?`, options:[`Teaching word meanings in context with multiple exposures and student interaction with words`,`Having students look up definitions in a dictionary`,`Teaching isolated word lists without context`,`Relying solely on incidental learning from reading`], answer:0, explanation:`Research shows that intentional vocabulary instruction with context, repetition, and active engagement leads to better retention and application.`, verified:true },
  { id:"b-reading-18", subtest:"reading", question:`A student encounters the word 'predict' and uses context clues from the sentence 'The scientist will predict the results of the experiment' to infer meaning. Which context clue type is being used?`, options:[`Definition clue`,`Inference from situation`,`Synonym clue`,`Example clue`], answer:1, explanation:`The student infers meaning from the situation described (a scientist and an experiment context), showing contextual inference rather than a direct definition or synonym.`, verified:true },
  { id:"b-reading-19", subtest:"reading", question:`Which pair of words has a morphological relationship?`, options:[`cat, cut`,`moon, soon`,`run, runner`,`big, large`], answer:2, explanation:`'Run' and 'runner' share a common morpheme (root 'run') with the suffix '-er' added, showing clear morphological structure.`, verified:true },
  { id:"b-reading-20", subtest:"reading", question:`A teacher displays the sentence 'The happy children played in the park' and asks students to identify words that describe. Which semantic relationship is the teacher emphasizing?`, options:[`Antonyms`,`Synonyms`,`Categories`,`Attributes (adjectives)`], answer:3, explanation:`The teacher is asking students to identify descriptive words (adjectives like 'happy'), which are words that show attributes or qualities.`, verified:true },
  { id:"b-reading-21", subtest:"reading", question:`When reading aloud, a student reads at a slow, choppy pace with frequent pauses between words. Which fluency component needs the most instructional focus?`, options:[`Rate and automaticity`,`Accuracy`,`Prosody`,`Expression`], answer:0, explanation:`The student's slow pace and choppy rhythm indicate low automaticity (word recognition) and rate, the primary concerns for this reader.`, verified:true },
  { id:"b-reading-22", subtest:"reading", question:`A student misreads 'The cat went home' as 'The cat went to home,' which is grammatically incorrect. This miscue indicates the student is NOT using which cueing system effectively?`, options:[`Graphophonic cues`,`Syntactic cues`,`Semantic cues`,`Visual cues`], answer:1, explanation:`The student ignored syntactic (grammatical) cues, as 'went to home' is not standard English syntax. A reader monitoring syntax would self-correct.`, verified:true },
  { id:"b-reading-23", subtest:"reading", question:`Which word contains the prefix that means 'not'?`, options:[`unusual`,`undo`,`unhappy`,`All of the above`], answer:3, explanation:`The prefix 'un-' means 'not,' and all three examples (unusual, undo, unhappy) contain it.`, verified:true },
  { id:"b-reading-24", subtest:"reading", question:`A second-grade teacher wants to assess whether students can identify the main idea of a passage. Which comprehension strategy would be MOST appropriate?`, options:[`Ask students to list all details they remember`,`Ask students to retell the passage word-for-word`,`Ask students to identify unknown vocabulary`,`Ask students to identify the most important idea and supporting details`], answer:3, explanation:`Identifying the main idea and its supporting details is the core strategy for main-idea comprehension, not mere recall or vocabulary work.`, verified:true },
  { id:"b-reading-25", subtest:"reading", question:`Read: 'Maria's backpack was very heavy. She struggled to carry it up the stairs.' What can the reader infer about Maria's strength?`, options:[`Maria may not be very strong or is tired`,`Maria is very strong`,`Maria likes to carry heavy things`,`Maria's backpack is always heavy`], answer:0, explanation:`The reader infers that Maria may lack strength or be tired, based on her struggling with the backpack. This is a reasonable inference from text evidence.`, verified:true },
  { id:"b-reading-26", subtest:"reading", question:`Which text structure is being used in the passage: 'Penguins live in Antarctica. They eat fish and krill. They are black and white'?`, options:[`Chronological order`,`Description`,`Cause and effect`,`Compare and contrast`], answer:1, explanation:`The passage describes characteristics of penguins (where they live, what they eat, how they look), using a descriptive text structure.`, verified:true },
  { id:"b-reading-27", subtest:"reading", question:`A student reads 'The fox was sly' and asks, 'What does sly mean?' The teacher responds by asking, 'What did the fox do in the story that showed it was clever?' Which comprehension strategy is the teacher modeling?`, options:[`Using a dictionary`,`Skipping unknown words`,`Using context clues and inference`,`Rereading from the beginning`], answer:2, explanation:`The teacher is guiding the student to use context clues and inference from the fox's actions to understand the meaning of 'sly.'`, verified:true },
  { id:"b-reading-28", subtest:"reading", question:`Which story element is typically introduced FIRST in a narrative?`, options:[`The conflict`,`The resolution`,`The climax`,`The setting and characters`], answer:3, explanation:`Stories typically begin by introducing the setting (where and when) and characters (who), establishing context before conflict and action develop.`, verified:true },
  { id:"b-reading-29", subtest:"reading", question:`Read: 'The author describes the rainforest as 'a place where every leaf holds a secret.' This phrase suggests the author's attitude toward the rainforest is one of:`, options:[`Wonder and respect`,`Indifference`,`Criticism`,`Confusion`], answer:0, explanation:`The poetic, mysterious language ('every leaf holds a secret') conveys wonder and respect, revealing a positive, reverent attitude.`, verified:true },
  { id:"b-reading-30", subtest:"reading", question:`Which strategy would be MOST effective for a teacher to use when a student struggles to understand a complex informational passage?`, options:[`Have the student read it again silently without support`,`Use a graphic organizer to help the student organize main ideas and details`,`Give the student the answer key`,`Ask the student to write a summary without rereading`], answer:1, explanation:`Graphic organizers help students visually organize information, making complex text more accessible and improving comprehension.`, verified:true },
  { id:"b-reading-31", subtest:"reading", question:`A teacher reads a folktale to first graders and asks, 'Why did the character make that choice?' This question targets which comprehension level?`, options:[`Literal comprehension`,`Evaluative comprehension`,`Inferential comprehension`,`Vocabulary comprehension`], answer:2, explanation:`Asking 'why' requires students to infer reasoning beyond literal text details, making it an inferential question.`, verified:true },
  { id:"b-reading-32", subtest:"reading", question:`Which organizational structure is used in an informational text that explains 'First, plants need water. Second, they need sunlight. Finally, they need nutrients'?`, options:[`Cause and effect`,`Compare and contrast`,`Description`,`Chronological or sequential order`], answer:3, explanation:`The sequence of steps (first, second, finally) shows a sequential or chronological organization.`, verified:true },
  { id:"b-reading-33", subtest:"reading", question:`A teacher wants to help students understand the difference between a biography and a fictional story. Which approach is MOST effective?`, options:[`Read examples of each and discuss facts vs. imagination, and author's purpose`,`Define both terms and have students memorize the definitions`,`Have students only read biographies for a week`,`Tell students biographies are always long`], answer:0, explanation:`Comparing real examples and discussing purpose, factuality, and imagination builds deeper understanding than isolated definitions.`, verified:true },
  { id:"b-reading-34", subtest:"reading", question:`A student accurately reads a decodable text with 92% word accuracy but cannot answer comprehension questions about the main idea. What does this indicate?`, options:[`The student needs more phonics instruction`,`The student can decode but struggles with comprehension; comprehension instruction is needed`,`The student is not trying hard enough`,`The text is too easy for the student`], answer:1, explanation:`Decoding accuracy does not guarantee comprehension. This student needs explicit comprehension strategy instruction.`, verified:true },
  { id:"b-reading-35", subtest:"reading", question:`Which sentence demonstrates strong sentence-combining skills?`, options:[`The cat was black. The cat was fluffy. The cat sat.`,`The cat was black and the cat was fluffy and the cat sat.`,`The black, fluffy cat sat down.`,`Cat black fluffy sat.`], answer:2, explanation:`Combining related ideas into one fluid sentence ('The black, fluffy cat sat down.') shows strong sentence-combining; the others overuse 'and' or lack clarity.`, verified:true },
  { id:"b-reading-36", subtest:"reading", question:`A student writes 'I like to play with my frends.' Which developmental spelling stage does this demonstrate?`, options:[`Pre-phonetic`,`Phonetic`,`Conventional`,`Transitional`], answer:3, explanation:`'Frends' shows the student knows most spelling patterns (phonetic) but hasn't yet mastered the standard spelling of 'friends,' indicating transitional spelling.`, verified:true },
  { id:"b-reading-37", subtest:"reading", question:`Which revision best corrects the run-on sentence: 'The dog ran in the park and he chased the ball and he got very tired'?`, options:[`The dog ran in the park. He chased the ball. He got very tired.`,`The dog ran in the park and he chased the ball and he got very tired.`,`The dog he ran in the park and chased the ball and got tired.`,`The dog ran and chased and got tired.`], answer:0, explanation:`Breaking the run-on into separate sentences or using varied punctuation creates clarity and proper sentence structure.`, verified:true },
  { id:"b-reading-38", subtest:"reading", question:`Which sentence is punctuated correctly?`, options:[`When the bell rings we will go to lunch.`,`When the bell rings, we will go to lunch.`,`When, the bell rings we will go to lunch.`,`When the bell rings we, will go to lunch.`], answer:1, explanation:`A comma is needed after an introductory dependent clause: 'When the bell rings, we will go to lunch.'`, verified:true },
  { id:"b-reading-39", subtest:"reading", question:`A teacher is working with students on the editing stage of the writing process. Which activity is MOST appropriate?`, options:[`Brainstorming ideas for a new story`,`Rewriting paragraphs for clarity and flow`,`Checking for spelling, punctuation, and grammar errors`,`Sharing writing with a peer for feedback`], answer:2, explanation:`Editing focuses on correctness (spelling, grammar, punctuation), while revision focuses on content and clarity. This question asks about editing.`, verified:true },
  { id:"b-reading-40", subtest:"reading", question:`Which word is spelled correctly?`, options:[`recieve`,`receve`,`recive`,`receive`], answer:3, explanation:`'Receive' follows the rule 'I before E except after C' (or when sounding like 'ay' as in 'eight').`, verified:true },
  { id:"b-reading-41", subtest:"reading", question:`A second-grader writes 'I goed to the store.' The teacher should address which grammatical concept?`, options:[`Irregular verb conjugation`,`Capitalization`,`Subject-verb agreement`,`Pronoun usage`], answer:0, explanation:`'Went' is the irregular past tense of 'go,' not 'goed.' The student needs instruction on irregular verbs.`, verified:true },
  { id:"b-reading-42", subtest:"reading", question:`During the writing process, the revision stage typically involves which activity?`, options:[`Fixing spelling and punctuation`,`Reorganizing ideas for clarity and adding descriptive details`,`Publishing the final copy`,`Initial brainstorming`], answer:1, explanation:`Revision is about improving content, organization, and clarity, not just mechanics (which is editing).`, verified:true },
  { id:"b-reading-43", subtest:"reading", question:`A student reads 'I saw a butterfly' when the text said 'I saw a dragonfly.' Which cueing system was prioritized, and what does this reveal?`, options:[`Syntactic cues; the student understands grammar but not word-letter details`,`Graphophonic cues; the student attended to initial letter /d/ but not subsequent letters`,`Semantic cues; the student substituted a similar insect, showing meaning-making but weak decoding`,`Visual cues; the student made a pure visual error`], answer:2, explanation:`The substitution of a semantically similar word (both are insects) while ignoring graphophonic details shows the student used semantic sense but didn't decode carefully.`, verified:true },
  { id:"b-reading-44", subtest:"reading", question:`A running record shows the following errors for a 120-word passage: 4 words misread, 2 words omitted, 1 word inserted, and 2 self-corrections. What is the accuracy percentage?`, options:[`92%`,`90%`,`96%`,`94%`], answer:3, explanation:`Errors = 4 + 2 + 1 = 7 (self-corrections are not counted as errors). Accuracy = (120 - 7) / 120 = 113/120 = 94%.`, verified:true },
  { id:"b-reading-45", subtest:"reading", question:`A kindergarten teacher holds up a picture of a cat and a picture of a dog and says, 'These are the same because they are both animals.' Which concept is being introduced?`, options:[`Categorization`,`Rhyming`,`Sequencing`,`Sound isolation`], answer:0, explanation:`Placing items into categories (animals) is a foundational comprehension and vocabulary concept.`, verified:true },
  { id:"b-reading-46", subtest:"reading", question:`Which activity is LEAST effective for building phonemic awareness in early kindergarten?`, options:[`Clapping syllables in words`,`Singing alphabet songs`,`Blending and segmenting sounds in words`,`Matching rhyming pictures`], answer:1, explanation:`Alphabet songs teach letter names (alphabet knowledge), not phonemic awareness. Clapping, blending, segmenting, and rhyming are all phonemic/phonological awareness activities.`, verified:true },
  { id:"b-reading-47", subtest:"reading", question:`A first-grader reads 'the cat' as two separate sounds /t/ /c/ instead of blending them. What should the teacher focus on?`, options:[`Sight word memorization of 'the'`,`Sound isolation`,`Phoneme blending strategies`,`Sentence fluency`], answer:2, explanation:`The student needs explicit instruction in blending individual phonemes into words, a core decoding skill.`, verified:true },
  { id:"b-reading-48", subtest:"reading", question:`Which instructional practice is based on the principle that repeated reading improves fluency?`, options:[`Having students read a different book each day`,`Having students read silently without feedback`,`Assigning independent reading only`,`Having students read the same decodable text multiple times with teacher guidance`], answer:3, explanation:`Research shows that repeated reading of the same text increases automaticity and fluency more effectively than new text each day.`, verified:true },
  { id:"b-reading-49", subtest:"reading", question:`A student encounters the word 'unimportant' and uses knowledge of the prefix 'un-' and the root 'important' to decode. This strategy demonstrates:`, options:[`Morphemic analysis`,`Context clue usage`,`Syllable segmentation only`,`Sight word recognition`], answer:0, explanation:`Breaking a word into morphemes (prefix + root) to decode and understand is morphemic analysis, a key advanced decoding strategy.`, verified:true },
  { id:"b-reading-50", subtest:"reading", question:`Which reading assessment BEST measures a student's instructional reading level?`, options:[`Silent reading of grade-level text with comprehension questions`,`A running record on text at the student's instructional level with 90-94% accuracy`,`Retelling after hearing a story read aloud`,`Answering factual questions about a familiar story`], answer:1, explanation:`A running record with 90-94% accuracy is the gold standard for identifying instructional level, where the student can read with teacher support.`, verified:true },
  { id:"b-reading-51", subtest:"reading", question:`A teacher provides a graphic organizer with boxes for 'Character,' 'Setting,' 'Problem,' and 'Solution' before students read a story. What is the teacher's primary goal?`, options:[`Forcing students to memorize story elements`,`Eliminating the need for reading the story`,`Scaffolding comprehension by organizing story elements visually`,`Testing prior knowledge`], answer:2, explanation:`Graphic organizers scaffold understanding by providing a visual framework for organizing key story elements during and after reading.`, verified:true },
  { id:"b-reading-52", subtest:"reading", question:`Which sentence follows correct capitalization and punctuation rules for dialogue?`, options:[`"look out!" said tim.`,`Look out! said "Tim".`,`"Look out said Tim."`,`"Look out!" said Tim.`], answer:3, explanation:`Dialogue requires a capital letter at the start of the quoted speech, proper punctuation inside the quotes, and proper capitalization of names.`, verified:true },
  { id:"b-reading-53", subtest:"reading", question:`A student demonstrates consistent difficulty substituting the first sound in a word (e.g., 'run' for 'sun'). This indicates weakness in:`, options:[`Phoneme substitution and awareness`,`Sight word recognition`,`Spelling ability`,`Fluency only`], answer:0, explanation:`Substituting initial phonemes suggests the student struggles with phoneme substitution, a key phonemic awareness skill.`, verified:true },
  { id:"b-reading-54", subtest:"reading", question:`Which prefix changes a word's meaning to indicate 'again' or 'backward'?`, options:[`un-`,`re-`,`pre-`,`dis-`], answer:1, explanation:`The prefix 're-' means 'again' or 'backward,' as in 'redo' (do again) or 'rewind' (wind backward).`, verified:true },
  { id:"b-reading-55", subtest:"reading", question:`A passage states: 'The library was packed with people during the rainstorm.' From this sentence, the reader can infer:`, options:[`The library is always full`,`The rainstorm was expected`,`The rainstorm caused people to go to the library`,`People dislike libraries`], answer:2, explanation:`The proximity of 'packed with people' and 'rainstorm' suggests a causal relationship—the rain drove people indoors to the library.`, verified:true },
  { id:"b-reading-56", subtest:"reading", question:`Which vowel team (digraph) is represented in the word 'boat'?`, options:[`oa and oa`,`ow`,`au`,`oa`], answer:3, explanation:`'Oa' is the vowel team in 'boat,' making the long-o sound.`, verified:true },
  { id:"b-reading-57", subtest:"reading", question:`A teacher uses think-aloud strategy while reading 'The boy looked worried. His exam was tomorrow.' The teacher says, 'I think the boy is worried because of the exam.' Which comprehension process is being modeled?`, options:[`Inference and cause-effect thinking`,`Phonemic awareness`,`Vocabulary instruction`,`Fluency practice`], answer:0, explanation:`The think-aloud models inference by connecting two pieces of information to understand why the character is worried.`, verified:true },
  { id:"b-reading-58", subtest:"reading", question:`Which spelling rule is demonstrated in the word 'stopped'?`, options:[`Add '-ed' to any verb to make past tense`,`Double the final consonant before adding '-ed' when the word has a short vowel`,`Never double consonants`,`Only add 'd' to words ending in 'p'`], answer:1, explanation:`'Stop' (short vowel + single consonant) doubles the 'p' before adding '-ed': stopped.`, verified:true },
  { id:"b-reading-59", subtest:"reading", question:`A second-grade teacher notices a student consistently reads 'teacher' as 'teecher' and 'water' as 'wader.' What does this pattern suggest?`, options:[`The student has not learned any vowel patterns`,`The student is guessing randomly`,`The student may be using phonetic decoding but misapplying vowel patterns`,`The student has a hearing problem`], answer:2, explanation:`The student is attempting to decode using sound-letter correspondences but is misapplying vowel patterns (treating 'ea' as 'ee' and 'er' as 'er' sound).`, verified:true },
  { id:"b-reading-60", subtest:"reading", question:`Which activity would be MOST appropriate for teaching the concept of homophones (words that sound the same but have different meanings)?`, options:[`Having students memorize a list of homophones`,`Teaching spelling rules`,`Focusing on phonics only`,`Writing sentences using 'son' and 'sun' in contexts that show different meanings`], answer:3, explanation:`Using homophones in meaningful contexts (sentences) helps students understand that words sounding alike can have very different meanings.`, verified:true },
  { id:"b-reading-61", subtest:"reading", question:`A student reads 'The little dog barked at the big cat' with perfect accuracy but in a flat, monotone voice with no expression. Which fluency component is the primary concern?`, options:[`Prosody and expression`,`Accuracy`,`Rate`,`Automaticity`], answer:0, explanation:`Prosody includes phrasing, expression, and intonation. This student has accuracy but lacks expressiveness in their reading.`, verified:true },
  { id:"b-reading-62", subtest:"reading", question:`A teacher asks students to sort word cards into 'rhymes with cat' and 'rhymes with dog' groups. Which reading skill is being assessed?`, options:[`Decoding`,`Phonological awareness (rhyming)`,`Comprehension`,`Syntax`], answer:1, explanation:`Sorting by rhyming patterns directly assesses phonological awareness, specifically rhyme awareness.`, verified:true },
  { id:"b-reading-63", subtest:"reading", question:`Which approach would BEST help a struggling reader understand the main idea of an informational text?`, options:[`Have the student read faster`,`Give the student the answer`,`Ask the student to identify topic words that appear repeatedly and key details that support the topic`,`Have the student look up every unknown word first`], answer:2, explanation:`Identifying repeated topic words and key supporting details is a research-based strategy for finding main ideas.`, verified:true },
  { id:"b-reading-64", subtest:"reading", question:`A kindergarten student points to a picture of an apple and says 'A.' What concept is the student demonstrating?`, options:[`Phonemic awareness`,`Decoding`,`Sight word recognition`,`Alphabetic principle`], answer:3, explanation:`The student is showing understanding of the alphabetic principle by connecting the letter 'A' to the initial sound and letter in 'apple.'`, verified:true },
  { id:"b-reading-65", subtest:"reading", question:`Which word pair demonstrates an antonymic (opposite) relationship?`, options:[`hot, cold`,`hot, heat`,`hot, temperature`,`hot, warm`], answer:0, explanation:`'Hot' and 'cold' are opposites (antonyms). 'Heat' is a related noun, 'warm' is a synonym, and 'temperature' is a broader category.`, verified:true },
  { id:"b-reading-66", subtest:"reading", question:`A teacher reads aloud: 'The brave firefighter rushed into the burning building.' Then asks, 'What kind of person is the firefighter?' Which strategy supports answering this question?`, options:[`Asking for the main idea`,`Using adjectives from the text to make inferences about character traits`,`Memorizing facts`,`Practicing pronunciation`], answer:1, explanation:`The adjective 'brave' directly describes the firefighter, and using text-based descriptors helps readers understand character traits.`, verified:true },
  { id:"b-reading-67", subtest:"reading", question:`A running record shows 87% accuracy. According to reading level research, this text is at the student's:`, options:[`Independent level`,`Instructional level`,`Frustration level`,`Guided reading level`], answer:2, explanation:`87% accuracy falls below 90%, which is the threshold for instructional level, placing this text in the frustration range (below 90%).`, verified:true },
  { id:"b-reading-68", subtest:"reading", question:`Which sentence demonstrates the use of a complex sentence structure?`, options:[`The cat is black.`,`The cat is black and white.`,`The cat, the dog, and the bird played.`,`Because the mouse ran away, the cat chased it.`], answer:3, explanation:`Option C uses a subordinate clause ('Because the mouse ran away') joined to an independent clause, creating a complex sentence.`, verified:true },
  { id:"b-reading-69", subtest:"reading", question:`A student uses the word 'bad' to mean 'really good' after hearing a peer use it that way. This demonstrates understanding of which concept?`, options:[`Connotation and shifts in word meaning based on context and dialect`,`Denotation only`,`Alphabetic principle`,`Phonics`], answer:0, explanation:`The student is picking up on connotation and the social context that can shift a word's meaning, showing sophisticated vocabulary awareness.`, verified:true },
  { id:"b-reading-70", subtest:"reading", question:`Which reading strategy would be LEAST effective for a student struggling with a dense informational passage?`, options:[`Breaking the passage into smaller chunks`,`Reading the passage once without support and expecting understanding`,`Previewing headings and pictures before reading`,`Using a graphic organizer to track main ideas`], answer:1, explanation:`Simply reading once without support is ineffective for struggling readers. Chunking, previewing, and organizing are all research-based strategies.`, verified:true },
  { id:"b-reading-71", subtest:"reading", question:`A first-grader reads 'ship' correctly but reads 'chin' as 'chih-in' (sounding out each letter). What does this suggest about the student's understanding?`, options:[`The student has mastered digraphs`,`The student cannot blend sounds`,`The student understands that 'ch' is a digraph in 'ship' but has not yet applied this pattern to 'chin'`,`The student needs to memorize 'chin' as a sight word`], answer:2, explanation:`The student knows the 'ch' digraph but has not yet generalized the pattern to a new word. Explicit instruction on pattern transfer is needed.`, verified:true },
  { id:"b-reading-72", subtest:"reading", question:`Which suffix changes a word into a comparative adjective?`, options:[`-ful`,`-ing`,`-tion`,`-er`], answer:3, explanation:`The suffix '-er' forms comparative adjectives (tall, taller; slow, slower).`, verified:true },
  { id:"b-reading-73", subtest:"reading", question:`A teacher displays a passage about penguins and asks, 'Where do penguins live?' The student answers 'Antarctica.' Which comprehension level is being assessed?`, options:[`Literal`,`Inferential`,`Evaluative`,`Interpretive`], answer:0, explanation:`The question asks for information directly stated in the text (literal comprehension), not inference or evaluation.`, verified:true },
  { id:"b-reading-74", subtest:"reading", question:`Which word exemplifies the open syllable pattern (vowel-consonant-vowel)?`, options:[`book`,`tiger`,`stand`,`frog`], answer:1, explanation:`'Tiger' (ti-ger) has an open syllable in the first syllable, where the vowel 'i' is followed by a consonant and another vowel, giving the 'i' a long sound.`, verified:true },
  { id:"b-reading-75", subtest:"reading", question:`A student writes 'The boy go to school' instead of 'The boy goes to school.' Which concept should the teacher address?`, options:[`Capitalization`,`Punctuation`,`Subject-verb agreement`,`Spelling`], answer:2, explanation:`The verb 'go' does not agree with the singular subject 'boy'; it should be 'goes.' This is a subject-verb agreement error.`, verified:true },
  { id:"b-reading-76", subtest:"reading", question:`A teacher notices a student consistently omits ending consonants when reading (e.g., 'run' for 'rung,' 'cat' for 'cats'). What should the teacher focus instruction on?`, options:[`Phonemic awareness of initial sounds only`,`Sight word memorization`,`Fluency only`,`Phoneme isolation and segmentation, especially final phonemes`], answer:3, explanation:`The student needs explicit instruction on identifying and segmenting final phonemes to address this decoding gap.`, verified:true },
  { id:"b-reading-77", subtest:"reading", question:`Which activity best supports the development of phonological awareness in early kindergarten?`, options:[`Clapping syllables and identifying rhymes`,`Tracing letters`,`Copying words from the board`,`Memorizing sight words`], answer:0, explanation:`Clapping and rhyming are direct phonological awareness activities. The others develop different skills (letter formation, sight words).`, verified:true },
  { id:"b-reading-78", subtest:"reading", question:`A student reads 'The boy walked to the park' with correct accuracy and fluency but cannot explain why the boy went to the park. What is the PRIMARY instructional need?`, options:[`More fluency practice`,`Explicit comprehension strategy instruction and inferencing practice`,`More decoding practice`,`Faster reading rate`], answer:1, explanation:`Decoding and fluency are strong; the gap is in comprehension (inference about motivation). Comprehension strategy instruction is needed.`, verified:true },
  { id:"b-reading-79", subtest:"reading", question:`Which of the following is the BEST example of a decodable text for early first grade?`, options:[`A book with irregular sight words and complex sentences`,`A book with long vowel patterns and multi-syllabic words`,`A book with CVC words, short vowels, and simple sentence structures`,`A picture book with minimal text`], answer:2, explanation:`Decodable text uses phonics patterns students have been explicitly taught. CVC words and short vowels are appropriate for early first grade.`, verified:true },
  { id:"b-reading-80", subtest:"reading", question:`A teacher is assessing listening comprehension by reading aloud and asking, 'What lesson did the main character learn?' Which type of thinking does this question target?`, options:[`Literal recall`,`Phonemic awareness`,`Decoding accuracy`,`Inference and theme identification`], answer:3, explanation:`Asking about a lesson learned requires students to infer the theme and understand deeper meaning beyond literal details.`, verified:true },
  { id:"b-math-1", subtest:"math", question:`In the number 4,827, the digit 8 represents:`, options:[`8 hundreds`,`8 tens`,`8 ones`,`8 thousands`], answer:0, explanation:`The 8 is in the hundreds place, so it represents 8 hundreds = 800.`, verified:true },
  { id:"b-math-2", subtest:"math", question:`Which is the expanded form of 2,408.3 ?`, options:[`(2×100)+(4×10)+(8×1)+(3×0.1)`,`(2×1000)+(4×100)+(8×1)+(3×0.1)`,`(2×1000)+(4×100)+(8×10)+(3×0.1)`,`(2×1000)+(48×10)+(3×0.01)`], answer:1, explanation:`2,408.3 = 2000 + 400 + 8 + 0.3.`, verified:true },
  { id:"b-math-3", subtest:"math", question:`1/3 + 1/6 = ?`, options:[`2/9`,`1/9`,`1/2`,`5/6`], answer:2, explanation:`Common denominator 6: 2/6 + 1/6 = 3/6 = 1/2.`, verified:true },
  { id:"b-math-4", subtest:"math", question:`2/5 × 3/4 = ?`, options:[`5/9`,`6/9`,`1/4`,`3/10`], answer:3, explanation:`Multiply across: 6/20 = 3/10.`, verified:true },
  { id:"b-math-5", subtest:"math", question:`3/4 ÷ 1/2 = ?`, options:[`1 1/2`,`3/8`,`2/3`,`6/8`], answer:0, explanation:`Multiply by the reciprocal: 3/4 × 2/1 = 6/4 = 1 1/2.`, verified:true },
  { id:"b-math-6", subtest:"math", question:`0.6 × 0.3 = ?`, options:[`1.8`,`0.18`,`0.9`,`0.018`], answer:1, explanation:`6 × 3 = 18; two decimal places → 0.18.`, verified:true },
  { id:"b-math-7", subtest:"math", question:`What is 35% of 60?`, options:[`18`,`24`,`21`,`15`], answer:2, explanation:`0.35 × 60 = 21.`, verified:true },
  { id:"b-math-8", subtest:"math", question:`12 is 25% of what number?`, options:[`3`,`36`,`60`,`48`], answer:3, explanation:`12 ÷ 0.25 = 48.`, verified:true },
  { id:"b-math-9", subtest:"math", question:`The ratio of cats to dogs is 3:5. If there are 24 animals total, how many are dogs?`, options:[`15`,`9`,`8`,`12`], answer:0, explanation:`3+5 = 8 parts; 24 ÷ 8 = 3 per part; dogs = 5 × 3 = 15.`, verified:true },
  { id:"b-math-10", subtest:"math", question:`If 4 notebooks cost $6, how much do 10 notebooks cost at the same rate?`, options:[`$12`,`$15`,`$24`,`$9`], answer:1, explanation:`Unit price 6 ÷ 4 = $1.50; × 10 = $15.`, verified:true },
  { id:"b-math-11", subtest:"math", question:`What is (−7) + 3?`, options:[`4`,`−10`,`−4`,`10`], answer:2, explanation:`Starting at −7 and moving up 3 gives −4.`, verified:true },
  { id:"b-math-12", subtest:"math", question:`What is 5 − (−8)?`, options:[`−3`,`−13`,`3`,`13`], answer:3, explanation:`Subtracting a negative adds: 5 + 8 = 13.`, verified:true },
  { id:"b-math-13", subtest:"math", question:`Evaluate: 2 + 6 ÷ 2 × 3`, options:[`11`,`12`,`6`,`14`], answer:0, explanation:`Left to right for ÷ and ×: 6÷2 = 3, ×3 = 9, then 2 + 9 = 11.`, verified:true },
  { id:"b-math-14", subtest:"math", question:`Which of these numbers is prime?`, options:[`21`,`29`,`27`,`33`], answer:1, explanation:`29 has no factors other than 1 and itself. 21=3×7, 27=3×9, 33=3×11.`, verified:true },
  { id:"b-math-15", subtest:"math", question:`What is the greatest common factor (GCF) of 12 and 18?`, options:[`3`,`2`,`6`,`12`], answer:2, explanation:`Factors shared by both: 1, 2, 3, 6 — the greatest is 6.`, verified:true },
  { id:"b-math-16", subtest:"math", question:`A store buys shirts for $8 each and sells them for $14 each. If it sells 25 shirts, what is the total profit?`, options:[`$350`,`$200`,`$50`,`$150`], answer:3, explanation:`Profit per shirt = 14 − 8 = $6; × 25 = $150.`, verified:true },
  { id:"b-math-17", subtest:"math", question:`Solve for x: 5x − 4 = 21`, options:[`x = 5`,`x = 3.4`,`x = 25`,`x = 4`], answer:0, explanation:`5x = 25 → x = 5.`, verified:true },
  { id:"b-math-18", subtest:"math", question:`Solve for x: 3(x + 2) = 18`, options:[`x = 6`,`x = 4`,`x = 8`,`x = 5`], answer:1, explanation:`3x + 6 = 18 → 3x = 12 → x = 4.`, verified:true },
  { id:"b-math-19", subtest:"math", question:`If a = 4 and b = 3, what is 2a + b² ?`, options:[`22`,`14`,`17`,`25`], answer:2, explanation:`2(4) + 3² = 8 + 9 = 17.`, verified:true },
  { id:"b-math-20", subtest:"math", question:`What is the next number in the pattern: 3, 7, 11, 15, ... ?`, options:[`18`,`20`,`17`,`19`], answer:3, explanation:`The pattern adds 4 each time: 15 + 4 = 19.`, verified:true },
  { id:"b-math-21", subtest:"math", question:`What comes next: 2, 6, 18, 54, ... ?`, options:[`162`,`108`,`216`,`150`], answer:0, explanation:`Each term is multiplied by 3: 54 × 3 = 162.`, verified:true },
  { id:"b-math-22", subtest:"math", question:`A taxi charges c = 3 + 2m dollars, where m is the number of miles driven. Which is the dependent variable?`, options:[`m, the miles driven`,`c, the cost`,`both variables`,`neither variable`], answer:1, explanation:`The cost c depends on the miles m, so c is the dependent variable.`, verified:true },
  { id:"b-math-23", subtest:"math", question:`A function follows the rule y = 4x − 1. When x = 3, y = ?`, options:[`7`,`12`,`11`,`13`], answer:2, explanation:`y = 4(3) − 1 = 12 − 1 = 11.`, verified:true },
  { id:"b-math-24", subtest:"math", question:`Which value of x makes the inequality 2x + 1 > 9 true?`, options:[`x = 3`,`x = 4`,`x = 2`,`x = 5`], answer:3, explanation:`2x > 8 → x > 4, so x = 5 works.`, verified:true },
  { id:"b-math-25", subtest:"math", question:`Maria is 4 years older than twice her brother's age. If her brother is 7, how old is Maria?`, options:[`18`,`11`,`15`,`22`], answer:0, explanation:`2 × 7 + 4 = 18.`, verified:true },
  { id:"b-math-26", subtest:"math", question:`Two numbers add to 20, and one is 4 more than the other. What is the larger number?`, options:[`8`,`12`,`10`,`16`], answer:1, explanation:`x + (x+4) = 20 → 2x = 16 → x = 8; larger = 12.`, verified:true },
  { id:"b-math-27", subtest:"math", question:`A phone plan costs $30 per month plus $0.10 per text. If the bill was $45, how many texts were sent?`, options:[`15`,`45`,`150`,`75`], answer:2, explanation:`45 − 30 = 15 in texts; 15 ÷ 0.10 = 150 texts.`, verified:true },
  { id:"b-math-28", subtest:"math", question:`If 3 workers build a wall in 12 hours, how long would 6 workers take at the same rate?`, options:[`24 hours`,`9 hours`,`3 hours`,`6 hours`], answer:3, explanation:`Total work = 3 × 12 = 36 worker-hours; 36 ÷ 6 workers = 6 hours.`, verified:true },
  { id:"b-math-29", subtest:"math", question:`What is the area of a triangle with a base of 8 cm and a height of 5 cm?`, options:[`20 cm²`,`40 cm²`,`13 cm²`,`26 cm²`], answer:0, explanation:`Area = ½ × base × height = ½ × 8 × 5 = 20 cm².`, verified:true },
  { id:"b-math-30", subtest:"math", question:`A rectangle measures 9 cm by 4 cm. What is its perimeter?`, options:[`36 cm`,`26 cm`,`13 cm`,`22 cm`], answer:1, explanation:`P = 2(9 + 4) = 2 × 13 = 26 cm.`, verified:true },
  { id:"b-math-31", subtest:"math", question:`What is the volume of a box that is 5 cm by 2 cm by 3 cm?`, options:[`10 cm³`,`31 cm³`,`30 cm³`,`60 cm³`], answer:2, explanation:`Volume = 5 × 2 × 3 = 30 cm³.`, verified:true },
  { id:"b-math-32", subtest:"math", question:`What is the area of a circle with a radius of 10 (use π ≈ 3.14)?`, options:[`31.4`,`62.8`,`100`,`314`], answer:3, explanation:`Area = πr² = 3.14 × 100 = 314.`, verified:true },
  { id:"b-math-33", subtest:"math", question:`What is the circumference of a circle with a diameter of 10 (use π ≈ 3.14)?`, options:[`31.4`,`314`,`15.7`,`62.8`], answer:0, explanation:`Circumference = π × diameter = 3.14 × 10 = 31.4.`, verified:true },
  { id:"b-math-34", subtest:"math", question:`Two angles of a triangle measure 50° and 60°. What is the third angle?`, options:[`80°`,`70°`,`90°`,`110°`], answer:1, explanation:`Angles total 180°: 180 − 50 − 60 = 70°.`, verified:true },
  { id:"b-math-35", subtest:"math", question:`How many feet are in 4 yards?`, options:[`8`,`48`,`12`,`16`], answer:2, explanation:`1 yard = 3 feet, so 4 × 3 = 12 feet.`, verified:true },
  { id:"b-math-36", subtest:"math", question:`How many grams are in 3 kilograms?`, options:[`300`,`30`,`30,000`,`3,000`], answer:3, explanation:`1 kg = 1,000 g, so 3 × 1,000 = 3,000 g.`, verified:true },
  { id:"b-math-37", subtest:"math", question:`In which quadrant of the coordinate plane is the point (−3, 5)?`, options:[`Quadrant II`,`Quadrant I`,`Quadrant III`,`Quadrant IV`], answer:0, explanation:`Negative x and positive y place the point in Quadrant II.`, verified:true },
  { id:"b-math-38", subtest:"math", question:`Find the mean (average) of 4, 8, 10, 6, and 12.`, options:[`10`,`8`,`6`,`9`], answer:1, explanation:`Sum = 40; 40 ÷ 5 = 8.`, verified:true },
  { id:"b-math-39", subtest:"math", question:`Find the mode of 3, 5, 5, 7, 9, 5, 2.`, options:[`3`,`7`,`5`,`2`], answer:2, explanation:`The mode is the most frequent value; 5 appears three times.`, verified:true },
  { id:"b-math-40", subtest:"math", question:`A standard six-sided die is rolled once. What is the probability of rolling a number greater than 4?`, options:[`1/2`,`2/3`,`1/6`,`1/3`], answer:3, explanation:`Numbers greater than 4 are {5, 6} = 2 of 6 = 1/3.`, verified:true },
  { id:"b-social-1", subtest:"social", question:`The first ten amendments to the U.S. Constitution are known as:`, options:[`The Bill of Rights`,`The Articles of Confederation`,`The Preamble`,`The Federalist Papers`], answer:0, explanation:`The first ten amendments are the Bill of Rights, ratified in 1791.`, verified:true },
  { id:"b-social-2", subtest:"social", question:`Which branch of government makes the laws?`, options:[`Executive`,`Legislative`,`Judicial`,`Bureaucratic`], answer:1, explanation:`The legislative branch (Congress) writes and passes laws.`, verified:true },
  { id:"b-social-3", subtest:"social", question:`Which branch of government enforces the laws?`, options:[`Legislative`,`Judicial`,`Executive`,`State`], answer:2, explanation:`The executive branch, led by the President, carries out and enforces laws.`, verified:true },
  { id:"b-social-4", subtest:"social", question:`Which branch of government interprets the laws?`, options:[`Executive`,`Legislative`,`State`,`Judicial`], answer:3, explanation:`The judicial branch (the courts) interprets laws and the Constitution.`, verified:true },
  { id:"b-social-5", subtest:"social", question:`The principle that keeps any one branch from becoming too powerful is:`, options:[`Checks and balances`,`Manifest destiny`,`Laissez-faire`,`Nullification`], answer:0, explanation:`Checks and balances lets each branch limit the powers of the others.`, verified:true },
  { id:"b-social-6", subtest:"social", question:`The Declaration of Independence was primarily written by:`, options:[`George Washington`,`Thomas Jefferson`,`Benjamin Franklin`,`Alexander Hamilton`], answer:1, explanation:`Thomas Jefferson was the primary author of the Declaration of Independence.`, verified:true },
  { id:"b-social-7", subtest:"social", question:`The phrase 'We the People' opens which document?`, options:[`The Declaration of Independence`,`The Bill of Rights`,`The Constitution (its Preamble)`,`The Emancipation Proclamation`], answer:2, explanation:`'We the People' begins the Preamble to the U.S. Constitution.`, verified:true },
  { id:"b-social-8", subtest:"social", question:`The system that divides power between a national government and state governments is:`, options:[`Anarchy`,`Monarchy`,`Oligarchy`,`Federalism`], answer:3, explanation:`Federalism divides power between national and state governments.`, verified:true },
  { id:"b-social-9", subtest:"social", question:`The Supreme Court's power to declare a law unconstitutional is called:`, options:[`Judicial review`,`Veto`,`Filibuster`,`Impeachment`], answer:0, explanation:`Judicial review allows courts to strike down laws that violate the Constitution.`, verified:true },
  { id:"b-social-10", subtest:"social", question:`How many amendments are currently in the U.S. Constitution?`, options:[`10`,`27`,`13`,`50`], answer:1, explanation:`There are 27 ratified amendments.`, verified:true },
  { id:"b-social-11", subtest:"social", question:`The Emancipation Proclamation, issued by President Lincoln, was intended to:`, options:[`End the Revolutionary War`,`Start the Civil War`,`Free enslaved people in the Confederate states`,`Create the Bill of Rights`], answer:2, explanation:`It declared enslaved people in Confederate-held territory to be free.`, verified:true },
  { id:"b-social-12", subtest:"social", question:`The Civil Rights Movement of the 1950s and 1960s primarily sought:`, options:[`Independence from Britain`,`Westward expansion`,`Lower federal taxes`,`Equal rights and an end to racial segregation`], answer:3, explanation:`It worked to end segregation and secure equal rights for Black Americans.`, verified:true },
  { id:"b-social-13", subtest:"social", question:`A primary responsibility of U.S. citizens is:`, options:[`Obeying laws and paying taxes`,`Owning property`,`Joining a political party`,`Earning a college degree`], answer:0, explanation:`Obeying laws and paying taxes are core civic responsibilities.`, verified:true },
  { id:"b-social-14", subtest:"social", question:`The right to a fair and speedy trial is guaranteed by the:`, options:[`First Amendment`,`Sixth Amendment`,`Tenth Amendment`,`Second Amendment`], answer:1, explanation:`The Sixth Amendment guarantees the right to a speedy and public trial.`, verified:true },
  { id:"b-social-15", subtest:"social", question:`Which body has the power to declare war?`, options:[`The President alone`,`The Supreme Court`,`Congress`,`State governors`], answer:2, explanation:`The Constitution gives Congress the power to declare war.`, verified:true },
  { id:"b-social-16", subtest:"social", question:`The President can reject a bill passed by Congress through a:`, options:[`Filibuster`,`Pardon`,`Subpoena`,`Veto`], answer:3, explanation:`A veto is the President's rejection of a bill.`, verified:true },
  { id:"b-social-17", subtest:"social", question:`The Boston Tea Party was a colonial protest against:`, options:[`British taxes (on tea)`,`French trade policy`,`Spanish colonial rule`,`The slave trade`], answer:0, explanation:`Colonists protested British taxation, dumping taxed tea into Boston Harbor.`, verified:true },
  { id:"b-social-18", subtest:"social", question:`The U.S. Constitution was written (signed) in the year:`, options:[`1776`,`1787`,`1812`,`1865`], answer:1, explanation:`The Constitution was signed at the Constitutional Convention in 1787.`, verified:true },
  { id:"b-social-19", subtest:"social", question:`Congress can override a presidential veto with a:`, options:[`Simple majority`,`Unanimous vote`,`Two-thirds vote of both houses`,`Supreme Court order`], answer:2, explanation:`A two-thirds vote in both the House and Senate overrides a veto.`, verified:true },
  { id:"b-social-20", subtest:"social", question:`The idea that government gets its authority from the 'consent of the governed' reflects:`, options:[`Federalism`,`Judicial review`,`Separation of powers`,`Popular sovereignty`], answer:3, explanation:`Power coming from the people is the principle of popular sovereignty.`, verified:true },
  { id:"b-social-21", subtest:"social", question:`Which is both a right and a responsibility reserved for U.S. citizens?`, options:[`Serving on a jury and voting`,`Paying sales tax`,`Obeying traffic laws`,`Attending public school`], answer:0, explanation:`Jury service and voting are rights and duties tied to citizenship.`, verified:true },
  { id:"b-social-22", subtest:"social", question:`The Underground Railroad was a network that helped:`, options:[`Build the transcontinental railroad`,`Enslaved people escape to freedom`,`Move troops during WWI`,`Deliver mail across the frontier`], answer:1, explanation:`It was a secret network helping enslaved people reach free states and Canada.`, verified:true },
  { id:"b-social-23", subtest:"social", question:`Which document was created FIRST?`, options:[`The U.S. Constitution`,`The Bill of Rights`,`The Declaration of Independence`,`The 13th Amendment`], answer:2, explanation:`The Declaration of Independence (1776) came before the Constitution (1787).`, verified:true },
  { id:"b-social-24", subtest:"social", question:`The branch of government that includes the President and the Cabinet is the:`, options:[`Legislative`,`Judicial`,`State`,`Executive`], answer:3, explanation:`The President and Cabinet are part of the executive branch.`, verified:true },
  { id:"b-social-25", subtest:"social", question:`Reconstruction refers to the period in U.S. history immediately following the:`, options:[`Civil War`,`Revolutionary War`,`First World War`,`Great Depression`], answer:0, explanation:`Reconstruction (1865–1877) followed the Civil War.`, verified:true },
  { id:"b-social-26", subtest:"social", question:`Lines of longitude on a globe run:`, options:[`East to west`,`North to south (pole to pole)`,`In complete circles around the middle`,`Diagonally`], answer:1, explanation:`Longitude lines (meridians) run north–south from pole to pole.`, verified:true },
  { id:"b-social-27", subtest:"social", question:`The imaginary line at 0° latitude is called the:`, options:[`Prime Meridian`,`Tropic of Cancer`,`Equator`,`International Date Line`], answer:2, explanation:`The Equator is located at 0° latitude.`, verified:true },
  { id:"b-social-28", subtest:"social", question:`The five themes of geography include location, place, movement, human-environment interaction, and:`, options:[`Climate`,`Population`,`Economy`,`Region`], answer:3, explanation:`The fifth theme is region.`, verified:true },
  { id:"b-social-29", subtest:"social", question:`A piece of land surrounded by water on three sides is a:`, options:[`Peninsula`,`Island`,`Isthmus`,`Plateau`], answer:0, explanation:`A peninsula is bordered by water on three sides.`, verified:true },
  { id:"b-social-30", subtest:"social", question:`Which is an example of human-environment interaction?`, options:[`A river flowing to the sea`,`Farmers building irrigation canals to water crops`,`Wind eroding a rock formation`,`A volcano erupting`], answer:1, explanation:`People modifying the land (irrigation) is human-environment interaction.`, verified:true },
  { id:"b-social-31", subtest:"social", question:`The largest continent by land area is:`, options:[`Africa`,`North America`,`Asia`,`Europe`], answer:2, explanation:`Asia is the largest continent in both area and population.`, verified:true },
  { id:"b-social-32", subtest:"social", question:`The typical long-term pattern of temperature and precipitation in a region is its:`, options:[`Forecast`,`Season`,`Daily weather`,`Climate`], answer:3, explanation:`Climate is the long-term average of weather conditions.`, verified:true },
  { id:"b-social-33", subtest:"social", question:`A map's key (or legend) is used to:`, options:[`Explain what the map's symbols mean`,`Display the map's title`,`Measure exact latitude`,`Show when the map was made`], answer:0, explanation:`The key explains the symbols and colors used on the map.`, verified:true },
  { id:"b-social-34", subtest:"social", question:`The permanent movement of people from one place to settle in another is called:`, options:[`Tourism`,`Migration`,`Trade`,`Recreation`], answer:1, explanation:`Migration is the movement of people to settle in a new location.`, verified:true },
  { id:"b-social-35", subtest:"social", question:`Culture includes a group's shared:`, options:[`Genetics and blood type`,`Height and weight`,`Language, beliefs, and customs`,`Eye color`], answer:2, explanation:`Culture is shared language, beliefs, traditions, and customs.`, verified:true },
  { id:"b-social-36", subtest:"social", question:`Which is an example of describing RELATIVE location?`, options:[`40° N, 105° W`,`A latitude of 0°`,`The Prime Meridian`,`Next to the school, across from the park`], answer:3, explanation:`Relative location describes a place in relation to other places.`, verified:true },
  { id:"b-social-37", subtest:"social", question:`A region that receives very little rainfall and has sparse vegetation is a:`, options:[`Desert`,`Rainforest`,`Wetland`,`Floodplain`], answer:0, explanation:`Low precipitation and sparse plant life describe a desert.`, verified:true },
  { id:"b-social-38", subtest:"social", question:`The Rocky Mountains are an example of a physical feature called a:`, options:[`Plain`,`Mountain range`,`River delta`,`Basin`], answer:1, explanation:`A long chain of connected mountains is a mountain range.`, verified:true },
  { id:"b-social-39", subtest:"social", question:`Most of Earth's surface is covered by:`, options:[`Deserts`,`Forests`,`Oceans`,`Mountains`], answer:2, explanation:`About 71% of Earth's surface is covered by oceans.`, verified:true },
  { id:"b-social-40", subtest:"social", question:`A compass rose on a map is used to show:`, options:[`The map's scale`,`The population`,`Elevation`,`Direction (N, S, E, W)`], answer:3, explanation:`A compass rose shows the cardinal directions.`, verified:true },
  { id:"b-social-41", subtest:"social", question:`The study of past human cultures through artifacts and remains is:`, options:[`Archaeology`,`Geology`,`Astronomy`,`Meteorology`], answer:0, explanation:`Archaeology studies past cultures through the objects they left behind.`, verified:true },
  { id:"b-social-42", subtest:"social", question:`The limited nature of resources compared to people's unlimited wants is called:`, options:[`Surplus`,`Scarcity`,`Profit`,`Demand`], answer:1, explanation:`Scarcity is the basic economic problem of limited resources.`, verified:true },
  { id:"b-social-43", subtest:"social", question:`The value of the next-best choice you give up when you make a decision is the:`, options:[`Tariff`,`Surplus`,`Opportunity cost`,`Subsidy`], answer:2, explanation:`Opportunity cost is the value of the alternative you forgo.`, verified:true },
  { id:"b-social-44", subtest:"social", question:`If demand for a product rises while the supply stays the same, the price usually:`, options:[`Falls`,`Stays exactly the same`,`Disappears`,`Rises`], answer:3, explanation:`Higher demand with unchanged supply pushes prices up.`, verified:true },
  { id:"b-social-45", subtest:"social", question:`Government decisions about its own spending and taxation are part of:`, options:[`Fiscal policy`,`Monetary policy`,`Foreign policy`,`Trade embargoes`], answer:0, explanation:`Fiscal policy is the government's use of spending and taxes.`, verified:true },
  { id:"b-social-46", subtest:"social", question:`Decisions by the Federal Reserve about interest rates and the money supply are part of:`, options:[`Fiscal policy`,`Monetary policy`,`Judicial policy`,`Immigration policy`], answer:1, explanation:`Monetary policy is controlled by the central bank (the Federal Reserve).`, verified:true },
  { id:"b-social-47", subtest:"social", question:`A tax placed on goods brought in from other countries is a:`, options:[`Subsidy`,`Quota`,`Tariff`,`Surplus`], answer:2, explanation:`A tariff is a tax on imported goods.`, verified:true },
  { id:"b-social-48", subtest:"social", question:`In a market economy, what mainly decides which goods are produced?`, options:[`The national government`,`A single central planner`,`The military`,`Supply and demand (consumers and producers)`], answer:3, explanation:`In a market economy, prices and consumer demand guide production.`, verified:true },
  { id:"b-social-49", subtest:"social", question:`The factors of production are land, labor, capital, and:`, options:[`Entrepreneurship`,`Taxes`,`Money`,`Profit`], answer:0, explanation:`The four factors of production are land, labor, capital, and entrepreneurship.`, verified:true },
  { id:"b-social-50", subtest:"social", question:`The Neolithic (Agricultural) Revolution led most directly to:`, options:[`The invention of the internet`,`Permanent settlements and farming`,`The Cold War`,`Human space travel`], answer:1, explanation:`Farming allowed people to settle permanently and form early communities.`, verified:true },
  { id:"b-social-51", subtest:"social", question:`Ancient Egyptian civilization developed primarily along which river?`, options:[`The Amazon`,`The Tigris`,`The Nile`,`The Yangtze`], answer:2, explanation:`Ancient Egypt grew along the Nile River.`, verified:true },
  { id:"b-social-52", subtest:"social", question:`Specialization and trade generally allow countries to:`, options:[`Produce fewer goods overall`,`Increase scarcity`,`Stop all imports`,`Obtain goods they cannot produce efficiently themselves`], answer:3, explanation:`Trade lets nations specialize and exchange for what they lack.`, verified:true },
  { id:"b-social-53", subtest:"social", question:`When a government spends more money than it collects in taxes, it runs a:`, options:[`Budget deficit`,`Budget surplus`,`Tariff`,`Profit`], answer:0, explanation:`Spending more than is collected creates a budget deficit.`, verified:true },
  { id:"b-social-54", subtest:"social", question:`Which is a feature of a command economy?`, options:[`Prices set freely by supply and demand`,`The government owns and controls production`,`Private businesses compete freely`,`Consumers decide what is produced`], answer:1, explanation:`In a command economy the government controls production and prices.`, verified:true },
  { id:"b-social-55", subtest:"social", question:`Early civilizations often developed near rivers mainly because rivers provided:`, options:[`Gold and silver`,`Protection from all invaders`,`Water for drinking, farming, and transportation`,`Cooler temperatures`], answer:2, explanation:`Rivers supplied water for crops, drinking, and transport, supporting settlement.`, verified:true },
  { id:"b-science-1", subtest:"science", question:`The three main types of rock are igneous, sedimentary, and:`, options:[`Metamorphic`,`Crystal`,`Mineral`,`Fossil`], answer:0, explanation:`The three rock types are igneous, sedimentary, and metamorphic.`, verified:true },
  { id:"b-science-2", subtest:"science", question:`The continuous movement of water through evaporation, condensation, and precipitation is the:`, options:[`Rock cycle`,`Water cycle`,`Carbon cycle`,`Food chain`], answer:1, explanation:`This describes the water cycle.`, verified:true },
  { id:"b-science-3", subtest:"science", question:`Earth's seasons are caused mainly by:`, options:[`The Moon's gravity`,`Earth's changing distance from the Sun`,`The tilt of Earth's axis`,`Ocean currents`], answer:2, explanation:`The 23.5° axial tilt changes how directly sunlight strikes each hemisphere.`, verified:true },
  { id:"b-science-4", subtest:"science", question:`The phases of the Moon are caused by:`, options:[`Clouds covering parts of it`,`The Moon physically changing shape`,`Earth's shadow falling on the Moon`,`Its changing position relative to Earth and the Sun`], answer:3, explanation:`We see different lit portions as the Moon orbits Earth. (Earth's shadow causes an eclipse, not phases.)`, verified:true },
  { id:"b-science-5", subtest:"science", question:`A lunar eclipse happens when:`, options:[`Earth's shadow falls on the Moon`,`The Moon blocks sunlight from reaching Earth`,`The Moon is simply full`,`Fog blocks the view of the Moon`], answer:0, explanation:`In a lunar eclipse, Earth passes between the Sun and Moon, casting its shadow on the Moon.`, verified:true },
  { id:"b-science-6", subtest:"science", question:`The slow breaking down of rock by wind, water, and ice is called:`, options:[`Deposition`,`Weathering`,`Condensation`,`Convection`], answer:1, explanation:`Weathering breaks rock into smaller pieces over time.`, verified:true },
  { id:"b-science-7", subtest:"science", question:`Most of Earth's fresh water is stored in:`, options:[`Rivers`,`Lakes`,`Glaciers and ice caps`,`Clouds`], answer:2, explanation:`The majority of fresh water is frozen in glaciers and polar ice.`, verified:true },
  { id:"b-science-8", subtest:"science", question:`The layer of gases surrounding Earth is the:`, options:[`Crust`,`Mantle`,`Core`,`Atmosphere`], answer:3, explanation:`The atmosphere is the envelope of gases around Earth.`, verified:true },
  { id:"b-science-9", subtest:"science", question:`Sudden shaking of the ground caused by the movement of tectonic plates is a(n):`, options:[`Earthquake`,`Hurricane`,`Tornado`,`Drought`], answer:0, explanation:`Plate movement along faults produces earthquakes.`, verified:true },
  { id:"b-science-10", subtest:"science", question:`Which planet is closest to the Sun?`, options:[`Venus`,`Mercury`,`Earth`,`Mars`], answer:1, explanation:`Mercury is the closest planet to the Sun.`, verified:true },
  { id:"b-science-11", subtest:"science", question:`The long-term average pattern of temperature and precipitation in a region is its:`, options:[`Daily forecast`,`Weather front`,`Climate`,`Humidity`], answer:2, explanation:`Climate is the long-term average; weather is the short-term state.`, verified:true },
  { id:"b-science-12", subtest:"science", question:`Igneous rock forms when:`, options:[`Layers of sediment are pressed together`,`Heat and pressure change existing rock`,`Shells and remains pile up`,`Molten rock (magma or lava) cools and hardens`], answer:3, explanation:`Igneous rock forms from cooled, solidified magma or lava.`, verified:true },
  { id:"b-science-13", subtest:"science", question:`The Sun is best classified as a:`, options:[`Star`,`Planet`,`Comet`,`Moon`], answer:0, explanation:`The Sun is a star at the center of our solar system.`, verified:true },
  { id:"b-science-14", subtest:"science", question:`A student tests whether fertilizer affects plant growth, but she also gives one plant more sunlight than the other. The results are NOT valid because:`, options:[`She did not name the plants`,`She changed more than one variable at a time`,`She used living plants`,`She measured the plants' height`], answer:1, explanation:`Two variables (fertilizer and light) differ, so the experiment is confounded — only one should change.`, verified:true },
  { id:"b-science-15", subtest:"science", question:`Sediment dropped by a river where it empties into a larger body of water often builds a:`, options:[`Volcano`,`Canyon`,`River delta`,`Glacier`], answer:2, explanation:`Deposited sediment at a river's mouth forms a delta.`, verified:true },
  { id:"b-science-16", subtest:"science", question:`One full rotation of Earth on its axis takes about:`, options:[`One year`,`One month`,`One week`,`One day (about 24 hours)`], answer:3, explanation:`Earth rotates once on its axis about every 24 hours, causing day and night.`, verified:true },
  { id:"b-science-17", subtest:"science", question:`The basic building block (smallest living unit) of all living things is the:`, options:[`Cell`,`Atom`,`Molecule`,`Organ`], answer:0, explanation:`The cell is the smallest unit of life.`, verified:true },
  { id:"b-science-18", subtest:"science", question:`The organelle that releases energy from food, often called the 'powerhouse of the cell,' is the:`, options:[`Nucleus`,`Mitochondria`,`Ribosome`,`Vacuole`], answer:1, explanation:`Mitochondria produce energy (ATP) through cellular respiration.`, verified:true },
  { id:"b-science-19", subtest:"science", question:`Plants make their own food from sunlight, water, and carbon dioxide through:`, options:[`Respiration`,`Digestion`,`Photosynthesis`,`Transpiration`], answer:2, explanation:`Photosynthesis converts light energy into stored chemical energy (glucose).`, verified:true },
  { id:"b-science-20", subtest:"science", question:`During photosynthesis, plants release which gas into the air?`, options:[`Carbon dioxide`,`Nitrogen`,`Hydrogen`,`Oxygen`], answer:3, explanation:`Plants take in carbon dioxide and release oxygen.`, verified:true },
  { id:"b-science-21", subtest:"science", question:`In the food chain grass → rabbit → fox, the rabbit is a:`, options:[`Primary consumer`,`Producer`,`Secondary consumer`,`Decomposer`], answer:0, explanation:`The rabbit eats the producer (grass), making it a primary consumer.`, verified:true },
  { id:"b-science-22", subtest:"science", question:`Organisms that break down dead matter and return nutrients to the soil are:`, options:[`Producers`,`Decomposers`,`Predators`,`Herbivores`], answer:1, explanation:`Decomposers (like fungi and bacteria) recycle nutrients from dead material.`, verified:true },
  { id:"b-science-23", subtest:"science", question:`An organism that makes its own food is called a:`, options:[`Consumer`,`Decomposer`,`Producer`,`Predator`], answer:2, explanation:`Producers (such as green plants) make their own food.`, verified:true },
  { id:"b-science-24", subtest:"science", question:`A characteristic passed from parents to offspring through genes is a(n):`, options:[`Learned trait`,`Acquired trait`,`Practiced skill`,`Inherited trait`], answer:3, explanation:`Genetically transmitted characteristics are inherited traits.`, verified:true },
  { id:"b-science-25", subtest:"science", question:`Which body system is responsible for breathing and gas exchange?`, options:[`The respiratory system`,`The digestive system`,`The circulatory system`,`The skeletal system`], answer:0, explanation:`The respiratory system handles breathing and oxygen/carbon dioxide exchange.`, verified:true },
  { id:"b-science-26", subtest:"science", question:`In an experiment, the factor that is measured as the result or outcome is the:`, options:[`Control`,`Dependent variable`,`Independent variable`,`Hypothesis`], answer:1, explanation:`The dependent variable is the measured outcome; the independent variable is what you change.`, verified:true },
  { id:"b-science-27", subtest:"science", question:`A testable, educated prediction that an experiment is designed to investigate is a:`, options:[`Conclusion`,`Result`,`Hypothesis`,`Variable`], answer:2, explanation:`A hypothesis is a testable proposed explanation or prediction.`, verified:true },
  { id:"b-science-28", subtest:"science", question:`A polar bear's thick fur and layer of fat are best described as:`, options:[`Learned behaviors`,`Random accidents`,`Diseases`,`Adaptations to its cold environment`], answer:3, explanation:`These inherited features help the bear survive its environment — adaptations.`, verified:true },
  { id:"b-science-29", subtest:"science", question:`A statement based on directly using the senses or taking a measurement is a(n):`, options:[`Observation`,`Inference`,`Opinion`,`Theory`], answer:0, explanation:`An observation uses direct sensing or measurement; an inference is an interpretation.`, verified:true },
  { id:"b-science-30", subtest:"science", question:`A caterpillar changing into a butterfly is an example of:`, options:[`Photosynthesis`,`Metamorphosis`,`Hibernation`,`Pollination`], answer:1, explanation:`Metamorphosis is a major change in body form during an organism's development.`, verified:true },
  { id:"b-science-31", subtest:"science", question:`The one factor a scientist deliberately changes in an experiment is the:`, options:[`Dependent variable`,`Constant`,`Independent variable`,`Observation`], answer:2, explanation:`The independent variable is the factor the experimenter changes on purpose.`, verified:true },
  { id:"b-science-32", subtest:"science", question:`Herbivores are animals that eat:`, options:[`Only meat`,`Only other predators`,`Only insects`,`Only plants`], answer:3, explanation:`Herbivores eat plants.`, verified:true },
  { id:"b-science-33", subtest:"science", question:`The transfer of pollen that allows many plants to reproduce is called:`, options:[`Pollination`,`Germination`,`Respiration`,`Erosion`], answer:0, explanation:`Pollination moves pollen so plants can form seeds.`, verified:true },
  { id:"b-science-34", subtest:"science", question:`The three common states of matter are solid, liquid, and:`, options:[`Plasma`,`Gas`,`Pure energy`,`A mixture`], answer:1, explanation:`The three common states are solid, liquid, and gas.`, verified:true },
  { id:"b-science-35", subtest:"science", question:`Ice melting into liquid water is an example of a:`, options:[`Chemical change`,`Nuclear change`,`Physical change`,`Combustion reaction`], answer:2, explanation:`Melting changes form but not the substance, so it is a physical change.`, verified:true },
  { id:"b-science-36", subtest:"science", question:`Which of the following is a CHEMICAL change?`, options:[`Boiling water`,`Cutting paper`,`Melting butter`,`Burning wood`], answer:3, explanation:`Burning produces new substances (ash, gases), so it is a chemical change.`, verified:true },
  { id:"b-science-37", subtest:"science", question:`A gas changing directly into a solid without first becoming a liquid is called:`, options:[`Deposition`,`Sublimation`,`Condensation`,`Evaporation`], answer:0, explanation:`Gas → solid is deposition.`, verified:true },
  { id:"b-science-38", subtest:"science", question:`A solid changing directly into a gas (like dry ice) without becoming a liquid is called:`, options:[`Deposition`,`Sublimation`,`Melting`,`Freezing`], answer:1, explanation:`Solid → gas is sublimation (the opposite of deposition).`, verified:true },
  { id:"b-science-39", subtest:"science", question:`Density is calculated as:`, options:[`Mass × volume`,`Volume ÷ mass`,`Mass ÷ volume`,`Mass + volume`], answer:2, explanation:`Density = mass ÷ volume.`, verified:true },
  { id:"b-science-40", subtest:"science", question:`An object has a mass of 30 g and a volume of 6 cm³. What is its density?`, options:[`180 g/cm³`,`0.2 g/cm³`,`36 g/cm³`,`5 g/cm³`], answer:3, explanation:`Density = 30 ÷ 6 = 5 g/cm³.`, verified:true },
  { id:"b-science-41", subtest:"science", question:`The force that pulls objects down toward the center of Earth is:`, options:[`Gravity`,`Friction`,`Magnetism`,`Tension`], answer:0, explanation:`Gravity pulls objects toward Earth.`, verified:true },
  { id:"b-science-42", subtest:"science", question:`The force that opposes motion between two surfaces that are touching is:`, options:[`Gravity`,`Friction`,`Inertia`,`Buoyancy`], answer:1, explanation:`Friction resists motion between surfaces in contact.`, verified:true },
  { id:"b-science-43", subtest:"science", question:`A unit used to measure force is the:`, options:[`Joule`,`Watt`,`Newton`,`Volt`], answer:2, explanation:`Force is measured in newtons (joule = energy, watt = power, volt = electric potential).`, verified:true },
  { id:"b-science-44", subtest:"science", question:`When you rub your hands together quickly, mechanical energy is converted mainly into:`, options:[`Light energy`,`Sound energy`,`Chemical energy`,`Heat (thermal) energy`], answer:3, explanation:`Friction converts motion into heat.`, verified:true },
  { id:"b-science-45", subtest:"science", question:`Which of the following is a simple machine?`, options:[`A lever`,`A computer`,`A car engine`,`A battery`], answer:0, explanation:`A lever is one of the six classic simple machines.`, verified:true },
  { id:"b-science-46", subtest:"science", question:`A plant measured 2 cm, 4 cm, 6 cm, and 8 cm over four weeks. Following the pattern, its height in week 5 will most likely be:`, options:[`8 cm`,`10 cm`,`12 cm`,`9 cm`], answer:1, explanation:`The plant grows 2 cm each week, so week 5 is about 10 cm.`, verified:true },
  { id:"b-science-47", subtest:"science", question:`A material that lets electricity flow through it easily is called a:`, options:[`Insulator`,`Magnet`,`Conductor`,`Resistor`], answer:2, explanation:`Conductors (like metals) allow electric current to flow easily.`, verified:true },
  { id:"b-science-48", subtest:"science", question:`The energy stored in a stretched rubber band is a form of:`, options:[`Thermal energy`,`Sound energy`,`Nuclear energy`,`Stored (potential) energy`], answer:3, explanation:`A stretched band stores elastic potential energy.`, verified:true },
  { id:"b-science-49", subtest:"science", question:`When light bounces off a surface, this is called:`, options:[`Reflection`,`Refraction`,`Absorption`,`Conduction`], answer:0, explanation:`Light bouncing off a surface is reflection.`, verified:true },
  { id:"b-science-50", subtest:"science", question:`When the like poles (for example, two north poles) of two magnets are brought together, they will:`, options:[`Attract each other`,`Repel each other`,`Have no effect`,`Melt together`], answer:1, explanation:`Like poles repel; opposite poles attract.`, verified:true },
  { id:"s-r1", subtest:"reading", topic:`Main idea`, passage:`Sea otters are a keystone species in Pacific kelp forests. By eating sea urchins, they keep urchin populations in check. Without otters, urchins multiply and graze kelp down to bare rock, destroying habitat for hundreds of other species.`, question:`Which sentence best states the main idea of the passage?`, options:[`Sea urchins are the most common animal in kelp forests.`,`Sea otters help sustain the whole kelp-forest ecosystem by controlling urchins.`,`Kelp grows only where there is bare rock.`,`Pacific kelp forests are found around the world.`], answer:1, explanation:`The passage centers on how otters, by eating urchins, protect the entire ecosystem — that is the controlling idea, not a supporting detail.`, verified:true },
  { id:"s-r2", subtest:"reading", topic:`Inference`, passage:`Maya checked the sky, sighed, and put the picnic basket back in the closet. She pulled a board game off the shelf instead.`, question:`What can the reader most reasonably infer?`, options:[`Maya dislikes board games.`,`The weather looked bad, so Maya changed plans.`,`Maya is going on a picnic later.`,`Maya lost the picnic basket.`], answer:1, explanation:`Checking the sky, sighing, and abandoning the picnic together imply the weather was unfavorable. Inference combines textual clues, not a stated fact.`, verified:true },
  { id:"s-r3", subtest:"reading", topic:`Vocabulary in context`, passage:`The committee's decision was not final; it was merely provisional, subject to change once more data arrived.`, question:`As used here, 'provisional' most nearly means:`, options:[`permanent`,`temporary`,`unanimous`,`secret`], answer:1, explanation:`'Not final ... subject to change' signals a temporary/tentative decision. Context defines the word.`, verified:true },
  { id:"s-r4", subtest:"reading", topic:`Phonics/decoding`, question:`A student reads 'phone' and 'graph' correctly. Which phonics skill are they demonstrating?`, options:[`Recognizing a digraph where two letters make one sound`,`Identifying a compound word`,`Using an inflectional ending`,`Applying the silent-e rule`], answer:0, explanation:`'ph' is a consonant digraph — two letters representing a single /f/ sound.`, verified:true },
  { id:"s-r5", subtest:"reading", topic:`Text structure`, passage:`First, the water cycle begins with evaporation. Next, water vapor rises and cools into clouds. Then precipitation falls. Finally, water collects and the cycle repeats.`, question:`Which text structure does this passage use?`, options:[`Compare and contrast`,`Cause and effect`,`Sequence/chronological order`,`Problem and solution`], answer:2, explanation:`Signal words 'First, Next, Then, Finally' mark a sequential/chronological structure.`, verified:true },
  { id:"s-r6", subtest:"reading", topic:`Author's purpose`, passage:`You should always wear a helmet when biking. It is the single most effective way to prevent serious head injury, and it takes only seconds to buckle.`, question:`The author's primary purpose is to:`, options:[`entertain the reader with a story`,`persuade the reader to wear a helmet`,`describe how a helmet is made`,`compare bikes and cars`], answer:1, explanation:`The passage argues a position ('You should always') with supporting reasons — persuasion.`, verified:true },
  { id:"s-r7", subtest:"reading", topic:`Fact vs opinion`, question:`Which statement is an opinion rather than a fact?`, options:[`Water boils at 100 degrees Celsius at sea level.`,`The novel has 312 pages.`,`Autumn is the most beautiful season of the year.`,`The meeting starts at 3 p.m.`], answer:2, explanation:`'Most beautiful' is a subjective judgment that cannot be verified — an opinion.`, verified:true },
  { id:"s-r8", subtest:"reading", topic:`Grammar/usage`, question:`Choose the sentence with correct subject-verb agreement.`, options:[`The team of players are ready.`,`Each of the students have a book.`,`Neither the teacher nor the students were late.`,`The group of children were quiet.`], answer:2, explanation:`With 'neither...nor', the verb agrees with the nearer subject ('students' → plural 'were'). 'Team,' 'each,' and 'group' take singular verbs, so the others are wrong.`, verified:true },
  { id:"s-r9", subtest:"reading", topic:`Context/reference`, question:`A teacher wants students to find the precise definition and part of speech of a word. Which resource is BEST?`, options:[`A thesaurus`,`A dictionary`,`An atlas`,`An almanac`], answer:1, explanation:`A dictionary gives definitions and parts of speech. A thesaurus gives synonyms, not definitions.`, verified:true },
  { id:"s-r10", subtest:"reading", topic:`Comprehension strategy`, question:`A student pauses while reading to ask, 'Does this make sense so far?' and rereads if not. This best illustrates:`, options:[`decoding`,`metacognition/self-monitoring`,`phonemic awareness`,`fluency`], answer:1, explanation:`Monitoring one's own understanding and adjusting is metacognitive self-monitoring.`, verified:true },
  { id:"s-r11", subtest:"reading", topic:`Figurative language`, passage:`The classroom was a zoo after the fire drill.`, question:`The sentence uses which device?`, options:[`Simile`,`Metaphor`,`Alliteration`,`Onomatopoeia`], answer:1, explanation:`It equates the classroom to a zoo directly, without 'like' or 'as' — a metaphor.`, verified:true },
  { id:"s-r12", subtest:"reading", topic:`Emergent literacy`, question:`Phonemic awareness is best described as the ability to:`, options:[`read words silently for meaning`,`hear and manipulate individual sounds in spoken words`,`write letters neatly`,`recognize sight words instantly`], answer:1, explanation:`Phonemic awareness is purely oral/auditory — identifying and manipulating individual phonemes in spoken words, no print involved.`, verified:true },
  { id:"s-r13", subtest:"reading", topic:`Supporting detail`, passage:`Recycling reduces waste in three ways. It keeps materials out of landfills, saves the energy needed to make new products, and conserves raw resources like timber and metal ore.`, question:`According to the passage, which is NOT a way recycling helps?`, options:[`Keeping materials out of landfills`,`Saving energy`,`Conserving raw resources`,`Lowering the price of new products`], answer:3, explanation:`Price is never mentioned; the other three are stated directly.`, verified:true },
  { id:"s-m1", subtest:"math", topic:`Fractions`, question:`What is 2/3 + 1/4?`, options:[`3/7`,`11/12`,`3/12`,`5/6`], answer:1, explanation:`Common denominator 12: 8/12 + 3/12 = 11/12.`, verified:true },
  { id:"s-m2", subtest:"math", topic:`Percent`, question:`A shirt costs $40 and is marked 25% off. What is the sale price?`, options:[`$10`,`$25`,`$30`,`$35`], answer:2, explanation:`25% of 40 = 10; 40 − 10 = 30.`, verified:true },
  { id:"s-m3", subtest:"math", topic:`Order of operations`, question:`Evaluate: 3 + 4 × 2² − 6 ÷ 3`, options:[`15`,`17`,`19`,`11`], answer:1, explanation:`2²=4; 4×4=16; 6÷3=2; 3+16−2 = 17.`, verified:true },
  { id:"s-m4", subtest:"math", topic:`Ratio/proportion`, question:`If 3 pencils cost $1.20, how much do 7 pencils cost at the same rate?`, options:[`$2.40`,`$2.80`,`$3.20`,`$4.20`], answer:1, explanation:`Unit price = 1.20/3 = $0.40; 7 × 0.40 = $2.80.`, verified:true },
  { id:"s-m5", subtest:"math", topic:`Algebra`, question:`Solve for x: 5x − 7 = 3x + 9`, options:[`x = 1`,`x = 8`,`x = 4`,`x = 2`], answer:1, explanation:`5x − 3x = 9 + 7 → 2x = 16 → x = 8.`, verified:true },
  { id:"s-m6", subtest:"math", topic:`Geometry — area`, question:`A rectangle is 12 cm long and 5 cm wide. What is its area?`, options:[`17 cm²`,`34 cm²`,`60 cm²`,`60 cm`], answer:2, explanation:`Area = length × width = 12 × 5 = 60 cm² (square units).`, verified:true },
  { id:"s-m7", subtest:"math", topic:`Geometry — perimeter`, question:`What is the perimeter of a square with side length 9 in?`, options:[`18 in`,`36 in`,`81 in`,`27 in`], answer:1, explanation:`Perimeter of a square = 4 × side = 4 × 9 = 36 in.`, verified:true },
  { id:"s-m8", subtest:"math", topic:`Statistics — mean`, question:`Find the mean of 4, 8, 10, 10, 18.`, options:[`10`,`9`,`12`,`8`], answer:0, explanation:`Sum = 50; 50 ÷ 5 = 10.`, verified:true },
  { id:"s-m9", subtest:"math", topic:`Statistics — median`, question:`Find the median of 7, 3, 9, 4, 12, 6.`, options:[`6`,`6.5`,`7`,`9`], answer:1, explanation:`Ordered: 3,4,6,7,9,12. Two middle values 6 and 7 → (6+7)/2 = 6.5.`, verified:true },
  { id:"s-m10", subtest:"math", topic:`Probability`, question:`A bag has 3 red, 2 blue, and 5 green marbles. What is the probability of drawing a blue marble?`, options:[`2/10`,`2/8`,`1/2`,`3/10`], answer:0, explanation:`Total = 10 marbles; blue = 2; P = 2/10 = 1/5.`, verified:true },
  { id:"s-m11", subtest:"math", topic:`Decimals`, question:`What is 0.6 × 0.4?`, options:[`2.4`,`0.24`,`0.024`,`0.1`], answer:1, explanation:`6 × 4 = 24; two decimal places total → 0.24.`, verified:true },
  { id:"s-m12", subtest:"math", topic:`Number sense`, question:`Which number is between 1/2 and 3/4?`, options:[`0.45`,`0.80`,`0.62`,`0.90`], answer:2, explanation:`1/2 = 0.5 and 3/4 = 0.75. Only 0.62 lies between them.`, verified:true },
  { id:"s-m13", subtest:"math", topic:`Word problem`, question:`A class of 28 students is split into groups of 4. How many groups are there?`, options:[`6`,`7`,`8`,`24`], answer:1, explanation:`28 ÷ 4 = 7 groups.`, verified:true },
  { id:"s-m14", subtest:"math", topic:`Exponents`, question:`What is the value of 2⁵?`, options:[`10`,`16`,`32`,`25`], answer:2, explanation:`2×2×2×2×2 = 32.`, verified:true },
  { id:"s-s1", subtest:"social", topic:`US government`, question:`Which branch of the U.S. federal government has the power to declare laws unconstitutional?`, options:[`Legislative`,`Executive`,`Judicial`,`State`], answer:2, explanation:`Judicial review — the power to strike down unconstitutional laws — belongs to the courts (judicial branch), established in Marbury v. Madison (1803).`, verified:true },
  { id:"s-s2", subtest:"social", topic:`US history`, question:`The Declaration of Independence was adopted in what year?`, options:[`1607`,`1776`,`1787`,`1812`], answer:1, explanation:`Adopted July 4, 1776. (1787 = Constitution written; 1607 = Jamestown founded.)`, verified:true },
  { id:"s-s3", subtest:"social", topic:`Constitution`, question:`The first ten amendments to the U.S. Constitution are collectively known as the:`, options:[`Articles of Confederation`,`Bill of Rights`,`Emancipation Proclamation`,`Federalist Papers`], answer:1, explanation:`The Bill of Rights (ratified 1791) is the first ten amendments.`, verified:true },
  { id:"s-s4", subtest:"social", topic:`Civics`, question:`Which document begins with the words 'We the People'?`, options:[`The Declaration of Independence`,`The U.S. Constitution`,`The Gettysburg Address`,`The Magna Carta`], answer:1, explanation:`The Preamble to the U.S. Constitution opens 'We the People of the United States...'`, verified:true },
  { id:"s-s5", subtest:"social", topic:`Geography`, question:`Lines that run east-west and measure distance north or south of the equator are called:`, options:[`longitude`,`latitude`,`meridians`,`time zones`], answer:1, explanation:`Latitude lines (parallels) run east-west and measure distance from the equator. Longitude runs north-south.`, verified:true },
  { id:"s-s6", subtest:"social", topic:`Economics`, question:`In economics, 'scarcity' refers to:`, options:[`the total money supply`,`limited resources relative to unlimited wants`,`a rise in prices over time`,`government spending`], answer:1, explanation:`Scarcity is the basic economic problem: resources are limited while human wants are unlimited. (Rising prices = inflation.)`, verified:true },
  { id:"s-s7", subtest:"social", topic:`US history`, question:`The American Civil War (1861–1865) was fought primarily over which central issue?`, options:[`Independence from Britain`,`Slavery and states' rights`,`Westward railroad routes`,`Prohibition of alcohol`], answer:1, explanation:`The war's central issue was slavery, tied to states' rights over its expansion.`, verified:true },
  { id:"s-s8", subtest:"social", topic:`Government structure`, question:`How many U.S. Senators does each state have?`, options:[`One`,`Two`,`Based on population`,`Four`], answer:1, explanation:`Every state has exactly two Senators regardless of population; House seats are population-based.`, verified:true },
  { id:"s-s9", subtest:"social", topic:`World history`, question:`The Industrial Revolution began in the late 1700s in which country?`, options:[`Germany`,`France`,`Great Britain`,`The United States`], answer:2, explanation:`It began in Great Britain, driven by textile machinery, the steam engine, and coal.`, verified:true },
  { id:"s-s10", subtest:"social", topic:`Geography`, question:`Which is the largest ocean on Earth?`, options:[`Atlantic`,`Indian`,`Arctic`,`Pacific`], answer:3, explanation:`The Pacific is the largest and deepest ocean.`, verified:true },
  { id:"s-s11", subtest:"social", topic:`Economics`, question:`In a market economy, prices are primarily determined by:`, options:[`the government`,`supply and demand`,`the largest company`,`international treaties`], answer:1, explanation:`In a market economy, the interaction of supply and demand sets prices.`, verified:true },
  { id:"s-s12", subtest:"social", topic:`Civic participation`, question:`Which is a responsibility (not just a right) of U.S. citizens?`, options:[`Freedom of speech`,`Serving on a jury when called`,`Owning property`,`Traveling between states`], answer:1, explanation:`Jury duty is a civic responsibility/duty; the others are rights.`, verified:true },
  { id:"s-s13", subtest:"social", topic:`US history`, question:`Who was the first President of the United States?`, options:[`Thomas Jefferson`,`John Adams`,`George Washington`,`Benjamin Franklin`], answer:2, explanation:`George Washington, inaugurated 1789. (Franklin was never president.)`, verified:true },
  { id:"s-sc1", subtest:"science", topic:`Life science — cells`, question:`Which cell structure is responsible for producing most of the cell's energy (ATP)?`, options:[`Nucleus`,`Ribosome`,`Mitochondrion`,`Cell wall`], answer:2, explanation:`The mitochondrion is the 'powerhouse' of the cell, producing ATP through cellular respiration.`, verified:true },
  { id:"s-sc2", subtest:"science", topic:`Life science — photosynthesis`, question:`Plants make their own food through photosynthesis, which requires sunlight, water, and:`, options:[`oxygen`,`carbon dioxide`,`nitrogen`,`salt`], answer:1, explanation:`Photosynthesis uses CO₂ + water + light energy to produce glucose and release oxygen.`, verified:true },
  { id:"s-sc3", subtest:"science", topic:`Physical science — states of matter`, question:`The change of a liquid directly into a gas is called:`, options:[`condensation`,`evaporation`,`sublimation`,`precipitation`], answer:1, explanation:`Liquid → gas = evaporation. (Solid → gas directly = sublimation; gas → liquid = condensation.)`, verified:true },
  { id:"s-sc4", subtest:"science", topic:`Earth science — water cycle`, question:`In the water cycle, the process by which water vapor cools and forms clouds is:`, options:[`evaporation`,`condensation`,`runoff`,`transpiration`], answer:1, explanation:`Condensation is water vapor cooling into tiny droplets that form clouds.`, verified:true },
  { id:"s-sc5", subtest:"science", topic:`Physical science — forces`, question:`Which force pulls objects toward the center of the Earth?`, options:[`Friction`,`Magnetism`,`Gravity`,`Buoyancy`], answer:2, explanation:`Gravity is the attractive force pulling masses together; on Earth it pulls objects toward the center.`, verified:true },
  { id:"s-sc6", subtest:"science", topic:`Earth/space — solar system`, question:`Which planet is closest to the Sun?`, options:[`Venus`,`Earth`,`Mercury`,`Mars`], answer:2, explanation:`Mercury is the innermost planet, closest to the Sun.`, verified:true },
  { id:"s-sc7", subtest:"science", topic:`Scientific inquiry`, question:`In an experiment, the variable that the scientist deliberately changes is the:`, options:[`dependent variable`,`independent variable`,`control`,`constant`], answer:1, explanation:`The independent variable is the one deliberately changed; the dependent variable is what is measured in response.`, verified:true },
  { id:"s-sc8", subtest:"science", topic:`Life science — ecosystems`, question:`In a food chain, organisms that make their own food are called:`, options:[`consumers`,`producers`,`decomposers`,`predators`], answer:1, explanation:`Producers (e.g., plants) make their own food via photosynthesis and form the base of the food chain.`, verified:true },
  { id:"s-sc9", subtest:"science", topic:`Physical science — matter`, question:`Water freezing into ice is an example of a:`, options:[`chemical change`,`physical change`,`nuclear change`,`chemical reaction`], answer:1, explanation:`Freezing changes state but not chemical identity (still H₂O) — a physical change, and it is reversible.`, verified:true },
  { id:"s-sc10", subtest:"science", topic:`Earth science — rocks`, question:`Rocks formed from cooled and hardened molten lava or magma are:`, options:[`sedimentary`,`metamorphic`,`igneous`,`mineral`], answer:2, explanation:`Igneous rocks form from cooled magma/lava. (Sedimentary = compacted sediment; metamorphic = heat/pressure altered.)`, verified:true },
  { id:"s-sc11", subtest:"science", topic:`Life science — body systems`, question:`Which body system is primarily responsible for transporting oxygen and nutrients throughout the body?`, options:[`Digestive`,`Circulatory`,`Respiratory`,`Skeletal`], answer:1, explanation:`The circulatory system (heart, blood, vessels) transports oxygen, nutrients, and wastes.`, verified:true },
  { id:"s-sc12", subtest:"science", topic:`Physical science — energy`, question:`A ball held at the top of a hill has the most of which type of energy?`, options:[`Kinetic energy`,`Gravitational potential energy`,`Thermal energy`,`Sound energy`], answer:1, explanation:`Stored energy due to height/position is gravitational potential energy; it converts to kinetic as the ball rolls down.`, verified:true },
  { id:"s-sc13", subtest:"science", topic:`Earth/space — moon`, question:`The phases of the Moon are caused by:`, options:[`the Earth's shadow on the Moon`,`the Moon's changing distance from Earth`,`the relative positions of the Sun, Earth, and Moon`,`clouds blocking part of the Moon`], answer:2, explanation:`Phases result from how much of the sunlit half of the Moon we see, based on Sun–Earth–Moon positions. (Earth's shadow causes eclipses, not phases.)`, verified:true }
];
